mapper.select:
SELECT YEAR(o.order_date) AS year, MONTH(o.order_date) AS month, SUM(o.total_amount) AS totalRevenue, COUNT(*) AS orderCount FROM orders o WHERE o.order_status != 'CANCELLED'
AND YEAR(o.order_date) = #{year}
GROUP BY YEAR(o.order_date), MONTH(o.order_date) ORDER BY year, month

SELECT oi.product_id AS productId, oi.product_name AS productName, SUM(oi.price * oi.quantity) AS totalRevenue, SUM(oi.quantity) AS quantitySold FROM order_items oi INNER JOIN orders o ON o.order_id = oi.order_id WHERE o.order_status != 'CANCELLED'
AND YEAR(o.order_date) = #{year}
AND MONTH(o.order_date) = #{month}
GROUP BY oi.product_id, oi.product_name ORDER BY totalRevenue DESC
